<?php
declare(strict_types=1);

require_once __DIR__ . '/../bootstrap/app.php';
require_once __DIR__ . '/../bootstrap/individual.php';
require_once __DIR__ . '/../bootstrap/management.php';
require_once __DIR__ . '/../bootstrap/consultation.php';
require_once __DIR__ . '/../bootstrap/overview.php';
pcp_apontamento_try_erp_handoff();
if (!empty($_SESSION[PCP_APONTAMENTO_SESSION]['authenticated']) && empty($_SESSION[PCP_APONTAMENTO_SESSION]['company_confirmed'])) { header('Location: ' . pcp_apontamento_url('select-company.php')); exit; }
if (!pcp_apontamento_context()) { header('Location: ' . pcp_apontamento_url('login.php')); exit; }
$context = pcp_apontamento_require_access();
$companyId = pcp_apontamento_require_company();
global $g;
$conn = $g['conexaoBanco'];
$pagina = array_key_exists('pagina', $_REQUEST) ? (string) $_REQUEST['pagina'] : ((isset($_REQUEST['matricula']) || $_SERVER['REQUEST_METHOD'] === 'POST') ? 'individual' : 'visao-geral');
// A rota antiga nunca processa POST nem chama o código coletivo removido.
if ($pagina === 'grupo' || ($_REQUEST['modo'] ?? '') === 'grupo') {
    pcp_apontamento_flash('error', 'O apontamento em grupo foi substituído pelo apontamento por matrícula.');
    header('Location: ' . pcp_apontamento_url('index.php?pagina=individual'));
    exit;
}
if ($pagina === 'configuracoes') { pcp_apontamento_management_page($conn, $context); exit; }
if ($pagina === 'gerenciar') {
    if (($_GET['ajax'] ?? '') === 'motivos_pausa_apontamento') {
        pcp_apontamento_require_edit();
        pcp_apontamento_json(['items'=>pcp_apontamento_motivos_pausa($conn)]);
    }
    if (($_GET['ajax'] ?? '') === 'buscar_colaborador_apontamento') {
        pcp_apontamento_require_edit();
        $matriculaBusca = pcp_apontamento_required_text($_GET['matricula'] ?? '', 250);
        $grupoBusca = pcp_apontamento_positive_int($_GET['pcp001_id'] ?? null);
        $grupoValido = $grupoBusca ? pcp_apontamento_one($conn, "SELECT PCP001.PCP001_Id AS id FROM PCP001 INNER JOIN T255 ON T255.T255_Id=PCP001.PCP001_T255_Id AND T255.T255_C004_Id=? WHERE PCP001.PCP001_Id=? AND PCP001.PCP001_Status='A' LIMIT 1", 'ii', [$companyId, $grupoBusca]) : null;
        $colaboradorBusca = ($matriculaBusca && $grupoValido) ? pcp_apontamento_colaborador($conn, $matriculaBusca) : null;
        pcp_apontamento_json(['item'=>$colaboradorBusca ? ['id'=>(int) $colaboradorBusca['id'], 'nome'=>(string) $colaboradorBusca['nome'], 'matricula'=>(string) $colaboradorBusca['matricula']] : null]);
    }
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        pcp_apontamento_require_csrf();
        $contextEdicao = pcp_apontamento_require_edit();
        $grupoEdicao = pcp_apontamento_positive_int($_POST['pcp001_id'] ?? null);
        $participanteEdicao = pcp_apontamento_positive_int($_POST['pcp002_id'] ?? null);
        try {
            $justificativa = pcp_apontamento_edicao_justificativa($_POST['justificativa'] ?? '');
            $acaoEdicao = (string) ($_POST['acao_edicao'] ?? '');
            if ($acaoEdicao === 'inativar_apontamento' && $grupoEdicao) {
                pcp_apontamento_inativar_apontamento($conn, $contextEdicao, $grupoEdicao, $justificativa);
                pcp_apontamento_flash('success', 'Apontamento inativado. O histórico foi preservado.');
            } elseif ($acaoEdicao === 'inativar_participante' && $grupoEdicao && $participanteEdicao) {
                pcp_apontamento_inativar_participante($conn, $contextEdicao, $grupoEdicao, $participanteEdicao, $justificativa);
                pcp_apontamento_flash('success', 'Participação do colaborador inativada. O apontamento foi mantido.');
            } elseif ($acaoEdicao === 'alterar_processo' && $grupoEdicao && ($processoEdicao = pcp_apontamento_positive_int($_POST['smt006_id'] ?? null))) {
                pcp_apontamento_editar_processo($conn, $contextEdicao, $grupoEdicao, $processoEdicao, $justificativa);
                pcp_apontamento_flash('success', 'Processo do apontamento alterado.');
            } elseif ($acaoEdicao === 'incluir_participante' && $grupoEdicao) {
                $matriculaEdicao = pcp_apontamento_required_text($_POST['matricula'] ?? '', 250);
                if ($matriculaEdicao === null) throw new DomainException('Informe uma matrícula válida.');
                $inicioEdicao = pcp_apontamento_edicao_data($_POST['inicio'] ?? '', 'o início');
                pcp_apontamento_adicionar_participante($conn, $contextEdicao, $grupoEdicao, $matriculaEdicao, $inicioEdicao, $justificativa);
                pcp_apontamento_flash('success', 'Colaborador incluído no apontamento.');
            } elseif ($acaoEdicao === 'alterar_horarios_participante' && $grupoEdicao && $participanteEdicao) {
                $inicioEdicao = pcp_apontamento_edicao_data($_POST['inicio'] ?? '', 'o início');
                $fimBruto = trim((string) ($_POST['fim'] ?? ''));
                $fimEdicao = $fimBruto === '' ? null : pcp_apontamento_edicao_data($fimBruto, 'o fim');
                pcp_apontamento_editar_participante($conn, $contextEdicao, $grupoEdicao, $participanteEdicao, $inicioEdicao, $fimEdicao, $justificativa);
                pcp_apontamento_flash('success', 'Horários do colaborador alterados.');
            } elseif ($acaoEdicao === 'alterar_evento' && $grupoEdicao && $participanteEdicao && ($eventoEdicao = pcp_apontamento_positive_int($_POST['pcp003_id'] ?? null))) {
                $dataEvento = pcp_apontamento_edicao_data($_POST['data_hora'] ?? '', 'a data/hora do evento');
                $motivoEvento = pcp_apontamento_positive_int($_POST['smt012_id'] ?? null);
                pcp_apontamento_editar_evento($conn, $contextEdicao, $grupoEdicao, $participanteEdicao, $eventoEdicao, $dataEvento, $motivoEvento, $justificativa);
                pcp_apontamento_flash('success', 'Evento do colaborador alterado.');
            } elseif ($acaoEdicao === 'incluir_evento' && $grupoEdicao && $participanteEdicao) {
                $dataEvento = pcp_apontamento_edicao_data($_POST['data_hora'] ?? '', 'a data/hora do evento');
                pcp_apontamento_adicionar_evento($conn, $contextEdicao, $grupoEdicao, $participanteEdicao, (string) ($_POST['tipo_evento'] ?? ''), $dataEvento, pcp_apontamento_positive_int($_POST['smt012_id'] ?? null), $justificativa);
                pcp_apontamento_flash('success', 'Evento incluído para o colaborador.');
            } elseif ($acaoEdicao === 'cancelar_evento' && $grupoEdicao && $participanteEdicao && ($eventoEdicao = pcp_apontamento_positive_int($_POST['pcp003_id'] ?? null))) {
                pcp_apontamento_cancelar_evento($conn, $contextEdicao, $grupoEdicao, $participanteEdicao, $eventoEdicao, $justificativa);
                pcp_apontamento_flash('success', 'Evento cancelado; o histórico foi preservado.');
            } else throw new DomainException('Solicitação de edição inválida.');
        } catch (Throwable $e) { pcp_apontamento_flash('error', $e instanceof DomainException ? $e->getMessage() : 'Não foi possível salvar a edição. ' . $e->getMessage()); }
        $retorno = ['pagina'=>'gerenciar'];
        if ($grupoEdicao) $retorno['detalhe'] = $grupoEdicao;
        header('Location: ' . pcp_apontamento_url('index.php?' . http_build_query($retorno))); exit;
    }
    try { $filtrosGestao = pcp_apontamento_consulta_filtros($_GET); }
    catch (DomainException $e) { $filtrosGestao = pcp_apontamento_consulta_filtros([]); pcp_apontamento_flash('error', $e->getMessage()); }
    $detalheId = pcp_apontamento_positive_int($_GET['detalhe'] ?? null);
    $detalhe = $detalheId ? pcp_apontamento_consulta_detalhe($conn, $companyId, $detalheId) : null;
    if ($detalheId && !$detalhe) pcp_apontamento_flash('error', 'Apontamento não encontrado para a empresa ativa.');
    $opcoesGestao = pcp_apontamento_consulta_opcoes($conn, $companyId);
    pcp_apontamento_header('Gerenciar apontamentos', $context);
    $statusTexto = ['A'=>'Aberto', 'P'=>'Pausado', 'F'=>'Finalizado', 'I'=>'Inativado'];
    $dataTela = static function (?string $data): string { return $data ? date('d/m/Y H:i', strtotime($data)) : '—'; };
    if ($detalhe): $grupoDetalhe = $detalhe['grupo']; $resumoOpDetalhe = pcp_apontamento_resumo_op($conn, $companyId, (int) $grupoDetalhe['op_id'], true); $processosEdicao = $context['can_edit'] ? pcp_apontamento_all($conn, "SELECT SMT006_Id AS id,SMT006_Descricao AS descricao FROM SMT006 WHERE SMT006_Flag_Apontamento='S' ORDER BY SMT006_Descricao") : []; ?>
        <a class="back-link" href="<?php echo pcp_apontamento_h(pcp_apontamento_url('index.php?pagina=gerenciar&' . http_build_query($filtrosGestao))); ?>">← Voltar à consulta</a>
        <section class="terminal-card management-detail"><div class="management-detail__head"><div><p class="eyebrow">Detalhe do apontamento #<?php echo (int) $grupoDetalhe['id']; ?></p><h2>OP #<?php echo (int) $grupoDetalhe['op_id']; ?> · <?php echo pcp_apontamento_h($grupoDetalhe['processo']); ?></h2><p class="management-detail__product"><small>Produto</small><?php echo pcp_apontamento_h(($resumoOpDetalhe['produto'] ?? '') ?: 'Não informado'); ?></p></div><?php if ($context['can_edit'] && $grupoDetalhe['status'] !== 'I'): ?><div class="management-detail__actions"><button type="button" class="secondary" data-pcp-open-inactivation="change-process-<?php echo (int) $grupoDetalhe['id']; ?>">Alterar processo</button><button type="button" class="secondary" data-pcp-open-inactivation="add-participant-<?php echo (int) $grupoDetalhe['id']; ?>">Incluir colaborador</button><button type="button" class="danger" data-pcp-open-inactivation="inactivate-group-<?php echo (int) $grupoDetalhe['id']; ?>">Inativar</button></div><?php endif; ?></div>
            <div class="detail-summary"><span><small>Cliente</small><?php echo pcp_apontamento_h($resumoOpDetalhe['cliente'] ?? 'Não informado'); ?></span><span><small>Início</small><?php echo pcp_apontamento_h($dataTela($grupoDetalhe['inicio'])); ?></span><span><small>Fim</small><?php echo pcp_apontamento_h($dataTela($grupoDetalhe['fim'])); ?></span><span><small>Tempo líquido do grupo</small><?php echo pcp_apontamento_h(pcp_apontamento_formata_tempo((int) $grupoDetalhe['tempo_liquido'])); ?></span><span><small>Status</small><b class="tag tag--<?php echo in_array($grupoDetalhe['status_operacional'], ['F','I'], true) ? 'off' : 'ok'; ?>"><?php echo $statusTexto[$grupoDetalhe['status_operacional']]; ?></b></span></div>
            <?php if ($context['can_edit'] && $grupoDetalhe['status'] !== 'I'): ?><dialog class="inactivation-dialog" id="inactivate-group-<?php echo (int) $grupoDetalhe['id']; ?>"><form method="post"><div class="inactivation-dialog__head"><p class="eyebrow">Confirmação necessária</p><h3>Inativar apontamento?</h3><p>Esta ação não apaga o histórico e inativa todos os colaboradores vinculados.</p></div><input type="hidden" name="csrf" value="<?php echo pcp_apontamento_h(pcp_apontamento_csrf_token()); ?>"><input type="hidden" name="pcp001_id" value="<?php echo (int) $grupoDetalhe['id']; ?>"><input type="hidden" name="acao_edicao" value="inativar_apontamento"><label>Justificativa<textarea name="justificativa" maxlength="500" required></textarea></label><div class="inactivation-dialog__actions"><button type="button" class="secondary" data-pcp-close-inactivation>Cancelar</button><button class="danger">Confirmar inativação</button></div></form></dialog><?php endif; ?>
            <?php if ($context['can_edit'] && $grupoDetalhe['status'] !== 'I'): ?><dialog class="inactivation-dialog" id="change-process-<?php echo (int) $grupoDetalhe['id']; ?>"><form method="post"><div class="inactivation-dialog__head"><p class="eyebrow">Editar apontamento</p><h3>Alterar processo</h3></div><input type="hidden" name="csrf" value="<?php echo pcp_apontamento_h(pcp_apontamento_csrf_token()); ?>"><input type="hidden" name="pcp001_id" value="<?php echo (int) $grupoDetalhe['id']; ?>"><input type="hidden" name="acao_edicao" value="alterar_processo"><label>Processo<select name="smt006_id" required><option value="">Selecione</option><?php foreach ($processosEdicao as $processo): ?><option value="<?php echo (int) $processo['id']; ?>"<?php echo (int) $processo['id'] === (int) $grupoDetalhe['processo_id'] ? ' selected' : ''; ?>><?php echo pcp_apontamento_h($processo['descricao']); ?></option><?php endforeach; ?></select></label><label>Justificativa<textarea name="justificativa" maxlength="500" required></textarea></label><div class="inactivation-dialog__actions"><button type="button" class="secondary" data-pcp-close-inactivation>Cancelar</button><button>Salvar processo</button></div></form></dialog><dialog class="inactivation-dialog" id="add-participant-<?php echo (int) $grupoDetalhe['id']; ?>"><form method="post"><div class="inactivation-dialog__head"><p class="eyebrow">Editar apontamento</p><h3>Incluir colaborador</h3><p>O início vem preenchido com o horário atual e pode ser alterado.</p></div><input type="hidden" name="csrf" value="<?php echo pcp_apontamento_h(pcp_apontamento_csrf_token()); ?>"><input type="hidden" name="pcp001_id" value="<?php echo (int) $grupoDetalhe['id']; ?>"><input type="hidden" name="acao_edicao" value="incluir_participante"><label>Matrícula<div class="lookup-inline"><input name="matricula" maxlength="250" required><button type="button" data-pcp-lookup-participant>Localizar</button></div></label><div class="participant-lookup-result" data-pcp-participant-result></div><label>Início<input type="datetime-local" name="inicio" value="<?php echo date('Y-m-d\\TH:i'); ?>" required></label><label>Justificativa<textarea name="justificativa" maxlength="500" required></textarea></label><div class="inactivation-dialog__actions"><button type="button" class="secondary" data-pcp-close-inactivation>Cancelar</button><button data-pcp-add-participant-submit disabled>Incluir colaborador</button></div></form></dialog><dialog class="inactivation-dialog" id="inactivate-group-<?php echo (int) $grupoDetalhe['id']; ?>"><form method="post"><div class="inactivation-dialog__head"><p class="eyebrow">Confirmação necessária</p><h3>Inativar apontamento?</h3><p>Esta ação não apaga o histórico e inativa todos os colaboradores vinculados.</p></div><input type="hidden" name="csrf" value="<?php echo pcp_apontamento_h(pcp_apontamento_csrf_token()); ?>"><input type="hidden" name="pcp001_id" value="<?php echo (int) $grupoDetalhe['id']; ?>"><input type="hidden" name="acao_edicao" value="inativar_apontamento"><label>Justificativa<textarea name="justificativa" maxlength="500" required></textarea></label><div class="inactivation-dialog__actions"><button type="button" class="secondary" data-pcp-close-inactivation>Cancelar</button><button class="danger">Confirmar inativação</button></div></form></dialog><?php endif; ?>
            <h3>Participantes</h3><div class="management-table"><table><thead><tr><th>Colaborador</th><th>Início</th><th>Fim</th><th>Status</th><th>Tempo líquido</th><?php if ($context['can_edit']): ?><th>Ações</th><?php endif; ?></tr></thead><tbody><?php foreach ($detalhe['participantes'] as $participante): ?><tr><td><?php echo pcp_apontamento_h($participante['nome']); ?></td><td><?php echo pcp_apontamento_h($dataTela($participante['inicio'])); ?></td><td><?php echo pcp_apontamento_h($dataTela($participante['fim'])); ?></td><td><?php echo pcp_apontamento_h($statusTexto[$participante['status']] ?? $participante['status']); ?></td><td><?php echo pcp_apontamento_h(pcp_apontamento_formata_tempo((int) $participante['tempo_liquido'])); ?></td><?php if ($context['can_edit']): ?><td><?php if ($participante['status'] !== 'I'): ?><button type="button" class="secondary participant-edit-button" data-pcp-open-inactivation="edit-participant-<?php echo (int) $participante['id']; ?>">Editar</button><dialog class="inactivation-dialog" id="edit-participant-<?php echo (int) $participante['id']; ?>"><div class="inactivation-dialog__head"><p class="eyebrow">Editar participação</p><h3><?php echo pcp_apontamento_h($participante['nome']); ?></h3><p>Altere os horários desta participação. O tempo líquido será recalculado pelos eventos registrados.</p></div><form method="post" class="participant-edit__form"><input type="hidden" name="csrf" value="<?php echo pcp_apontamento_h(pcp_apontamento_csrf_token()); ?>"><input type="hidden" name="pcp001_id" value="<?php echo (int) $grupoDetalhe['id']; ?>"><input type="hidden" name="pcp002_id" value="<?php echo (int) $participante['id']; ?>"><input type="hidden" name="acao_edicao" value="alterar_horarios_participante"><label>Início<input type="datetime-local" name="inicio" value="<?php echo pcp_apontamento_h(date('Y-m-d\\TH:i', strtotime($participante['inicio']))); ?>" required></label><label>Fim<input type="datetime-local" name="fim" value="<?php echo $participante['fim'] ? pcp_apontamento_h(date('Y-m-d\\TH:i', strtotime($participante['fim']))) : ''; ?>"<?php echo $participante['status'] === 'F' ? ' required' : ''; ?>></label><label>Justificativa<textarea name="justificativa" maxlength="500" required></textarea></label><div class="inactivation-dialog__actions"><button type="button" class="secondary" data-pcp-close-inactivation>Cancelar</button><button>Salvar alterações</button></div></form><div class="participant-edit__inactivate"><button type="button" class="danger" data-pcp-open-inactivation="inactivate-participant-<?php echo (int) $participante['id']; ?>">Inativar colaborador</button></div></dialog><dialog class="inactivation-dialog" id="inactivate-participant-<?php echo (int) $participante['id']; ?>"><form method="post"><div class="inactivation-dialog__head"><p class="eyebrow">Confirmação necessária</p><h3>Inativar colaborador?</h3><p>Remove apenas este colaborador do apontamento, preservando todo o histórico.</p></div><input type="hidden" name="csrf" value="<?php echo pcp_apontamento_h(pcp_apontamento_csrf_token()); ?>"><input type="hidden" name="pcp001_id" value="<?php echo (int) $grupoDetalhe['id']; ?>"><input type="hidden" name="pcp002_id" value="<?php echo (int) $participante['id']; ?>"><input type="hidden" name="acao_edicao" value="inativar_participante"><label>Justificativa<textarea name="justificativa" maxlength="500" required></textarea></label><div class="inactivation-dialog__actions"><button type="button" class="secondary" data-pcp-close-inactivation>Cancelar</button><button class="danger">Confirmar inativação</button></div></form></dialog><?php else: ?><span class="tag tag--off">Inativado</span><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div>
            <h3>Eventos por colaborador</h3><?php $eventosPorParticipante = []; foreach ($detalhe['eventos'] as $evento) { $chaveEvento = (int) $evento['participante_id']; $eventosPorParticipante[$chaveEvento]['nome'] = $evento['participante_nome'] ?: 'Evento do grupo'; $eventosPorParticipante[$chaveEvento]['eventos'][] = $evento; } foreach ($eventosPorParticipante as $blocoEvento): ?><section class="event-participant"><h4><?php echo pcp_apontamento_h($blocoEvento['nome']); ?></h4><div class="management-table"><table><thead><tr><th>Data/hora</th><th>Evento</th><th>Motivo de pausa</th><?php if ($context['can_edit']): ?><th>Ações</th><?php endif; ?></tr></thead><tbody><?php foreach ($blocoEvento['eventos'] as $evento): ?><?php $tipoEvento = ['I'=>'Início', 'P'=>'Pausa', 'R'=>'Retomada', 'F'=>'Finalização'][$evento['tipo']] ?? $evento['tipo']; ?><tr><td><?php echo pcp_apontamento_h($dataTela($evento['data_hora'])); ?></td><td><?php echo pcp_apontamento_h($tipoEvento); ?></td><td><?php echo pcp_apontamento_h($evento['motivo_pausa'] ?: '—'); ?></td><?php if ($context['can_edit']): ?><td><button type="button" class="secondary participant-edit-button" data-pcp-open-inactivation="edit-event-<?php echo (int) $evento['id']; ?>">Editar</button><dialog class="inactivation-dialog" id="edit-event-<?php echo (int) $evento['id']; ?>"><form method="post"><div class="inactivation-dialog__head"><p class="eyebrow">Editar evento</p><h3><?php echo pcp_apontamento_h($tipoEvento); ?></h3><p><?php echo in_array($evento['tipo'], ['I','F'], true) ? 'Este horário atualiza automaticamente a participação do colaborador.' : 'O evento deve permanecer dentro do período deste colaborador.'; ?></p></div><input type="hidden" name="csrf" value="<?php echo pcp_apontamento_h(pcp_apontamento_csrf_token()); ?>"><input type="hidden" name="pcp001_id" value="<?php echo (int) $grupoDetalhe['id']; ?>"><input type="hidden" name="pcp002_id" value="<?php echo (int) $evento['participante_id']; ?>"><input type="hidden" name="pcp003_id" value="<?php echo (int) $evento['id']; ?>"><input type="hidden" name="acao_edicao" value="alterar_evento"><label>Data e hora<input type="datetime-local" name="data_hora" value="<?php echo pcp_apontamento_h(date('Y-m-d\\TH:i', strtotime($evento['data_hora']))); ?>" required></label><?php if ($evento['tipo'] === 'P'): ?><label>Motivo da pausa<select name="smt012_id" required><option value="">Selecione</option><?php foreach (pcp_apontamento_motivos_pausa($conn) as $motivo): ?><option value="<?php echo (int) $motivo['id']; ?>"<?php echo $motivo['descricao'] === $evento['motivo_pausa'] ? ' selected' : ''; ?>><?php echo pcp_apontamento_h($motivo['descricao']); ?></option><?php endforeach; ?></select></label><?php endif; ?><label>Justificativa<textarea name="justificativa" maxlength="500" required></textarea></label><div class="inactivation-dialog__actions"><button type="button" class="secondary" data-pcp-close-inactivation>Cancelar</button><button>Salvar evento</button></div></form></dialog></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div></section><?php endforeach; ?>
            <?php if (!empty($detalhe['auditoria'])): ?>
                <section class="edit-history" data-pcp-group-history>
                    <h3>Histórico do apontamento</h3>
                    <div class="edit-history__list">
                        <?php foreach ($detalhe['auditoria'] as $registro):
                            $rotulosAuditoria = ['inativar_apontamento'=>'Apontamento inativado','inativar_participante'=>'Colaborador removido deste apontamento','alterar_processo'=>'Processo alterado','incluir_participante'=>'Colaborador incluído','alterar_horarios_participante'=>'Horários do colaborador alterados','alterar_evento_I'=>'Início alterado','alterar_evento_P'=>'Pausa alterada','alterar_evento_R'=>'Retomada alterada','alterar_evento_F'=>'Finalização alterada','incluir_evento_I'=>'Início incluído','incluir_evento_P'=>'Pausa incluída','incluir_evento_R'=>'Retomada incluída','incluir_evento_F'=>'Finalização incluída','cancelar_evento_P'=>'Pausa cancelada','cancelar_evento_R'=>'Retomada cancelada','cancelar_evento_F'=>'Finalização cancelada'];
                            $rotuloAuditoria = $rotulosAuditoria[$registro['acao']] ?? 'Alteração no apontamento';
                        ?>
