        <section class="terminal-card management-query"><p class="eyebrow">Consulta operacional</p><h2>Gerenciar apontamentos</h2><p>Consulte os registros da empresa ativa. Esta tela é somente leitura e não altera OPs, quantidades ou status.</p>
            <form method="get" class="management-filters"><input type="hidden" name="pagina" value="gerenciar"><label>Início de<input type="date" name="inicio_de" value="<?php echo pcp_apontamento_h($filtrosGestao['inicio_de'] ?? ''); ?>"></label><label>Início até<input type="date" name="inicio_ate" value="<?php echo pcp_apontamento_h($filtrosGestao['inicio_ate'] ?? ''); ?>"></label><label>OP<input type="number" min="1" name="op_id" value="<?php echo $filtrosGestao['op_id'] ? (int) $filtrosGestao['op_id'] : ''; ?>"></label><label>Matrícula<input name="matricula" maxlength="250" value="<?php echo pcp_apontamento_h($filtrosGestao['matricula']); ?>"></label><label>Processo<select name="processo_id"><option value="">Todos</option><?php foreach ($opcoesGestao['processos'] as $opcao): ?><option value="<?php echo (int) $opcao['id']; ?>"<?php echo $filtrosGestao['processo_id'] === (int) $opcao['id'] ? ' selected' : ''; ?>><?php echo pcp_apontamento_h($opcao['descricao']); ?></option><?php endforeach; ?></select></label><label>Colaborador<select name="colaborador_id"><option value="">Todos</option><?php foreach ($opcoesGestao['colaboradores'] as $opcao): ?><option value="<?php echo (int) $opcao['id']; ?>"<?php echo $filtrosGestao['colaborador_id'] === (int) $opcao['id'] ? ' selected' : ''; ?>><?php echo pcp_apontamento_h($opcao['nome']); ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><?php foreach (['todos'=>'Todos', 'aberto'=>'Aberto', 'pausado'=>'Pausado', 'finalizado'=>'Finalizado'] as $valor => $texto): ?><option value="<?php echo $valor; ?>"<?php echo $filtrosGestao['status'] === $valor ? ' selected' : ''; ?>><?php echo $texto; ?></option><?php endforeach; ?></select></label><button>Consultar</button></form>
