        <?php if (!$gruposGestao): ?><div class="empty-state"><strong>Nenhum apontamento encontrado</strong><span>Ajuste o período ou os filtros para consultar outros registros.</span></div><?php else: ?><div class="apontamento-cards"><?php foreach ($gruposGestao as $grupo): $dadosTempo = pcp_apontamento_consulta_detalhe($conn, $companyId, (int) $grupo['id']); $resumoOpGrupo = pcp_apontamento_resumo_op($conn, $companyId, (int) $grupo['op_id'], true); $grupoTempo = (int) $dadosTempo['grupo']['tempo_liquido']; $emExecucao = $grupo['status_operacional'] === 'A'; ?><article class="apontamento-card apontamento-card--<?php echo $grupo['status_operacional'] === 'F' ? 'finalizado' : ($grupo['status_operacional'] === 'P' ? 'pausado' : 'ativo'); ?>"><div class="apontamento-card__head"><span class="apontamento-card__op">OP #<?php echo (int) $grupo['op_id']; ?></span><span class="tag tag--<?php echo $grupo['status_operacional'] === 'F' ? 'off' : 'ok'; ?>"><?php echo $emExecucao ? 'Em execução' : $statusTexto[$grupo['status_operacional']]; ?></span></div><h3><?php echo pcp_apontamento_h($grupo['processo']); ?></h3><?php if ($resumoOpGrupo): ?><div class="apontamento-card__product"><span>Cliente</span><strong><?php echo pcp_apontamento_h($resumoOpGrupo['cliente'] ?: 'Não informado'); ?></strong></div><?php endif; ?><div class="apontamento-card__meta"><span>Início: <?php echo pcp_apontamento_h($dataTela($grupo['inicio'])); ?></span><?php if ($grupo['status_operacional'] === 'F'): ?><span>Finalizado: <?php echo pcp_apontamento_h($dataTela($grupo['fim'])); ?></span><?php endif; ?></div><div class="apontamento-card__time"><small><?php echo $emExecucao ? 'Tempo em execução' : ($grupo['status_operacional'] === 'P' ? 'Tempo pausado' : 'Tempo para finalizar'); ?></small><strong class="timer"<?php echo $emExecucao ? ' data-pcp-timer data-seconds="' . $grupoTempo . '" data-running="1"' : ''; ?>><?php echo pcp_apontamento_h(pcp_apontamento_formata_tempo($grupoTempo)); ?></strong></div><div class="apontamento-card__people"><strong>Participantes · <?php echo (int) $grupo['participantes']; ?></strong><div><?php foreach ($dadosTempo['participantes'] as $participante): ?><span class="participant-chip participant-chip--<?php echo strtolower($participante['status']); ?>"><?php echo pcp_apontamento_h($participante['nome'] . ($participante['matricula'] ? ' · Matrícula: ' . $participante['matricula'] : '') . ' · ' . ($statusTexto[$participante['status']] ?? $participante['status'])); ?></span><?php endforeach; ?></div></div><?php if ($grupo['retrabalho'] === 'S'): ?><p class="apontamento-card__rework">Retrabalho<?php echo $grupo['motivo_retrabalho'] ? ' · ' . pcp_apontamento_h($grupo['motivo_retrabalho']) : ''; ?></p><?php endif; ?><a class="button-link secondary-link" href="<?php echo pcp_apontamento_h(pcp_apontamento_url('index.php?pagina=gerenciar&detalhe=' . (int) $grupo['id'] . '&' . http_build_query($filtrosGestao))); ?>">Ver detalhes</a></article><?php endforeach; ?></div><?php endif; ?></section>
    <?php endif;
