if ($pagina === 'visao-geral') {
    $resumoVisaoGeral = pcp_apontamento_visao_geral_resumo($conn, $companyId);
    $gruposVisaoGeral = pcp_apontamento_visao_geral_grupos_abertos($conn, $companyId);
    $atalhosVisaoGeral = pcp_apontamento_visao_geral_atalhos((bool) $context['can_manage']);
    $dataTelaVisaoGeral = static function (string $data): string { return date('d/m/Y H:i', strtotime($data)); };
    pcp_apontamento_header('Visão geral', $context); ?>
