    <section class="quick-actions" aria-label="Ações rápidas"><?php foreach ($atalhosVisaoGeral as $atalho): ?><a class="quick-action <?php echo pcp_apontamento_h($atalho['classe']); ?>" href="<?php echo pcp_apontamento_h(pcp_apontamento_url('index.php?pagina=' . $atalho['pagina'])); ?>"><strong><?php echo pcp_apontamento_h($atalho['titulo']); ?></strong><span><?php echo pcp_apontamento_h($atalho['descricao']); ?></span><i>›</i></a><?php endforeach; ?></section>
    <section class="overview-summary" aria-label="Resumo operacional"><article><small>Apontamentos abertos</small><strong><?php echo $resumoVisaoGeral['grupos_abertos']; ?></strong></article><article><small>Participantes em atividade</small><strong><?php echo $resumoVisaoGeral['participantes_atividade']; ?></strong></article><article><small>Participantes pausados</small><strong><?php echo $resumoVisaoGeral['participantes_pausados']; ?></strong></article><article><small>Apontamentos iniciados hoje</small><strong><?php echo $resumoVisaoGeral['iniciados_hoje']; ?></strong></article></section>
    <section class="terminal-card overview-groups"><div class="section-head"><div><p class="eyebrow">Acompanhamento atual</p><h2>Apontamentos ativos</h2><p>Até 10 apontamentos abertos da empresa ativa.</p></div></div><?php if (!$gruposVisaoGeral): ?><div class="empty-state"><strong>Nenhum apontamento aberto</strong><span>Inicie um apontamento por matrícula para acompanhar a operação aqui.</span></div><?php else: ?><div class="overview-group-list"><?php foreach ($gruposVisaoGeral as $grupo): $pausado = !$grupo['em_execucao']; $corPausa = (string) ($grupo['motivo_pausa']['cor'] ?? ''); $estiloPausa = preg_match('/^#[0-9a-fA-F]{6}$/', $corPausa) ? ' style="--pause-color:' . pcp_apontamento_h($corPausa) . '"' : ''; ?><article class="overview-group<?php echo $pausado ? ' overview-group--paused' : ''; ?>"<?php echo $pausado ? $estiloPausa : ''; ?>><div><span class="apontamento-card__op">OP #<?php echo (int) $grupo['op_id']; ?></span><span class="tag <?php echo $pausado ? 'overview-pause-tag' : 'tag--ok'; ?>"><?php echo $pausado ? 'Pausado' : 'Aberto'; ?></span></div><h3><?php echo pcp_apontamento_h($grupo['processo']); ?></h3><p class="overview-group__mode"><?php echo pcp_apontamento_h($grupo['modalidade']); ?></p><?php if ($pausado && !empty($grupo['motivo_pausa']['descricao'])): ?><p class="overview-pause-reason">Pausa: <?php echo pcp_apontamento_h($grupo['motivo_pausa']['descricao']); ?></p><?php endif; ?><dl><div><dt>Início</dt><dd><?php echo pcp_apontamento_h($dataTelaVisaoGeral($grupo['inicio'])); ?></dd></div><div><dt>Tempo líquido atual</dt><dd class="timer"<?php echo $grupo['em_execucao'] ? ' data-pcp-timer data-seconds="' . (int) $grupo['tempo_liquido'] . '" data-running="1"' : ''; ?>>Tempo: <?php echo pcp_apontamento_h(pcp_apontamento_formata_tempo((int) $grupo['tempo_liquido'])); ?></dd></div><div><dt>Participantes</dt><dd><?php echo (int) $grupo['participantes']; ?></dd></div><div><dt>Pausados</dt><dd><?php echo (int) $grupo['pausados']; ?></dd></div></dl><?php if ($grupo['retrabalho'] === 'S'): ?><p class="apontamento-card__rework">Retrabalho</p><?php endif; ?><a class="button-link secondary-link" href="<?php echo pcp_apontamento_h(pcp_apontamento_url('index.php?pagina=gerenciar&detalhe=' . (int) $grupo['id'])); ?>">Ver apontamento</a></article><?php endforeach; ?></div><?php endif; ?></section>
    <?php pcp_apontamento_footer(); exit;
}
$matricula = pcp_apontamento_required_text($_REQUEST['matricula'] ?? '', 250) ?: '';
$opInformada = pcp_apontamento_positive_int($_REQUEST['op_id'] ?? null);
$exibirRetrabalho = (bool) pcp_apontamento_config('show_rework');
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    pcp_apontamento_require_csrf();
    $acao = (string) ($_POST['acao'] ?? '');
    $limparTerminalAposInicio = false;
    try {
        if ($acao === 'lookup_op') {
            $opId = pcp_apontamento_positive_int($_POST['op_id'] ?? null);
            if (!$opId || !pcp_apontamento_one($conn, "SELECT T255_Id FROM T255 WHERE T255_Id=? AND T255_C004_Id=? AND COALESCE(T255_Flag_Status,'0') != '99' LIMIT 1", 'ii', [$opId, $companyId])) throw new DomainException('OP não encontrada, finalizada ou sem acesso nesta empresa.');
            $opInformada = $opId;
        } elseif ($acao === 'start') {
            $opId = pcp_apontamento_positive_int($_POST['op_id'] ?? null); $smt006Id = pcp_apontamento_positive_int($_POST['smt006_id'] ?? null);
            $retrabalho = ($_POST['retrabalho'] ?? '') === 'S'; $motivo = pcp_apontamento_positive_int($_POST['motivo_retrabalho'] ?? null);
            if (!$matricula || !$opId || !$smt006Id) throw new DomainException('Informe matrícula, OP e processo.');
            $inicio = pcp_apontamento_inicio($conn, $context, $matricula, $opId, $smt006Id, $retrabalho, $motivo);
            pcp_apontamento_flash('success', $inicio['entrou_em_existente']
                ? 'Você entrou no apontamento aberto da OP #' . $opId . ' · ' . $inicio['processo'] . ' · ' . $inicio['participantes'] . ' participante(s) ativos.'
                : 'Apontamento iniciado.');
            $_SESSION[PCP_APONTAMENTO_SESSION]['flash']['dialog'] = 'inicio_concluido';
            // O flash sobrevive ao redirect, mas a matrícula/OP não: a estação
            // fica imediatamente pronta para registrar a próxima pessoa.
            $limparTerminalAposInicio = true;
        } elseif (in_array($acao, ['pause','resume','finish'], true)) {
            if (!$matricula) throw new DomainException('Informe a matrícula do colaborador.');
            pcp_apontamento_acao($conn, $context, $matricula, $acao, pcp_apontamento_positive_int($_POST['motivo_pausa'] ?? null));
            pcp_apontamento_flash('success', $acao === 'pause' ? 'Apontamento pausado.' : ($acao === 'resume' ? 'Apontamento retomado.' : 'Apontamento finalizado.'));
            if ($acao === 'finish') $_SESSION[PCP_APONTAMENTO_SESSION]['flash']['dialog'] = 'finalizacao_concluida';
        } else throw new DomainException('Solicitação inválida.');
    } catch (Throwable $e) {
        pcp_apontamento_flash('error', $e instanceof DomainException ? $e->getMessage() : 'Não foi possível concluir a operação.');
        if ($acao === 'lookup_op') {
            // A OP recebida no POST não é uma seleção válida até a consulta
            // confirmar empresa e status; não a mantenha na tela de fundo.
            $opInformada = null;
            $_SESSION[PCP_APONTAMENTO_SESSION]['flash']['inline_op'] = true;
        } elseif ($acao === 'start') {
            $_SESSION[PCP_APONTAMENTO_SESSION]['flash']['inline_op'] = true;
        }
    }
    $query = [];
    if (!$limparTerminalAposInicio && $matricula) $query['matricula'] = $matricula;
    if (!$limparTerminalAposInicio && $opInformada) $query['op_id'] = $opInformada;
        $query['pagina'] = 'individual';
        header('Location: ' . pcp_apontamento_url('index.php') . '?' . http_build_query($query));
    exit;
}
$colaborador = $matricula ? pcp_apontamento_colaborador($conn, $matricula) : null;
$aberto = $colaborador ? pcp_apontamento_aberto($conn, $companyId, (int) $colaborador['id']) : null;
$opcoes = ($colaborador && !$aberto) ? pcp_apontamento_opcoes_inicio($conn, $companyId, (int) $colaborador['id']) : ['ops'=>[], 'processos'=>[], 'retrabalho'=>[]];
$resumoOp = ($colaborador && !$aberto && $opInformada) ? pcp_apontamento_resumo_op($conn, $companyId, $opInformada) : null;
$resumoOpAberto = $aberto ? pcp_apontamento_resumo_op($conn, $companyId, (int) $aberto['op_id']) : null;
$motivosPausa = $aberto ? pcp_apontamento_motivos_pausa($conn) : [];
pcp_apontamento_header('Apontamento de Produção', $context);
?>
