        <?php if ($aberto): ?><?php $inicioBrasileiro = date('d/m/Y H:i:s', strtotime((string) $aberto['inicio'])); ?><div class="active-card"><strong>OP #<?php echo (int) $aberto['op_id']; ?> · <?php echo pcp_apontamento_h($aberto['processo']); ?></strong><?php if ($resumoOpAberto && !empty($resumoOpAberto['produto'])): ?><span class="active-card__product">Produto: <?php echo pcp_apontamento_h($resumoOpAberto['produto']); ?></span><?php endif; ?><?php if ($resumoOpAberto): ?><span>Quantidade prevista: <?php echo pcp_apontamento_h(number_format((float) $resumoOpAberto['quantidade_prevista'], 3, ',', '.')); ?> · Cliente: <?php echo pcp_apontamento_h($resumoOpAberto['cliente'] ?: 'Não informado'); ?></span><?php endif; ?><span>Início: <?php echo pcp_apontamento_h($inicioBrasileiro); ?> · <strong class="timer" data-pcp-timer data-seconds="<?php echo max(0, (int) $aberto['segundos']); ?>" data-running="<?php echo $aberto['status'] === 'A' ? '1' : '0'; ?>">Tempo: <?php echo gmdate('H:i:s', max(0, (int) $aberto['segundos'])); ?></strong> · <?php echo $aberto['status'] === 'P' ? 'Pausado' : 'Ativo'; ?><?php echo (int) $aberto['participantes_abertos'] > 1 ? ' · ' . (int) $aberto['participantes_abertos'] . ' participantes no apontamento' : ''; ?></span></div>
            <form method="post" class="actions"><input type="hidden" name="csrf" value="<?php echo pcp_apontamento_h(pcp_apontamento_csrf_token()); ?>"><input type="hidden" name="matricula" value="<?php echo pcp_apontamento_h($matricula); ?>">
            <?php if ($aberto['status'] === 'A'): ?><button type="button" data-pcp-open-pause>Pausar</button><dialog class="pause-dialog" data-pcp-pause-dialog><div class="pause-dialog__head"><p class="eyebrow">Pausa do apontamento</p><h3>Selecione o motivo</h3><p>O motivo é obrigatório e ficará registrado no evento de pausa.</p></div><label>Motivo de pausa<select name="motivo_pausa" required><option value="">Selecione o motivo</option><?php foreach ($motivosPausa as $motivo): ?><option value="<?php echo (int) $motivo['id']; ?>"><?php echo pcp_apontamento_h($motivo['descricao']); ?></option><?php endforeach; ?></select></label><div class="pause-dialog__actions"><button type="button" class="secondary" data-pcp-close-pause>Cancelar</button><button name="acao" value="pause">Confirmar pausa</button></div></dialog><?php else: ?><button name="acao" value="resume">Retomar</button><?php endif; ?><button class="danger" name="acao" value="finish" formnovalidate>Finalizar</button></form>
        <?php else: ?>
            <form method="post" class="start-form">
                <input type="hidden" name="csrf" value="<?php echo pcp_apontamento_h(pcp_apontamento_csrf_token()); ?>">
                <input type="hidden" name="matricula" value="<?php echo pcp_apontamento_h($matricula); ?>">
                <input type="hidden" name="op_id" value="<?php echo $opInformada ?: ''; ?>">
                <div class="op-selector"><span>OP</span><strong><?php echo $opInformada ? 'OP #' . (int) $opInformada . ' selecionada' : 'Nenhuma OP selecionada'; ?></strong><button type="button" data-pcp-open-op-dialog><?php echo $opInformada ? 'Alterar OP' : 'Localizar OP'; ?></button></div>
                <?php if ($resumoOp): ?><section class="op-summary" aria-label="Dados da OP selecionada"><?php if (!empty($resumoOp['produto'])): ?><strong><?php echo pcp_apontamento_h($resumoOp['produto']); ?></strong><?php endif; ?><span>Quantidade prevista: <?php echo pcp_apontamento_h(number_format((float) $resumoOp['quantidade_prevista'], 3, ',', '.')); ?><?php echo (int) $resumoOp['total_itens'] > 1 ? ' · ' . (int) $resumoOp['total_itens'] . ' itens na OP' : ''; ?></span><span>Cliente: <?php echo pcp_apontamento_h($resumoOp['cliente'] ?: 'Não informado'); ?></span></section><?php endif; ?>
                <label>Processo<select name="smt006_id" required<?php echo (!$opInformada || !$opcoes['processos']) ? ' disabled' : ''; ?>><option value=""><?php echo $opInformada && $opcoes['processos'] ? 'Selecione' : 'Localize uma OP primeiro'; ?></option><?php foreach ($opcoes['processos'] as $processo): ?><option value="<?php echo (int) $processo['smt006_id']; ?>"><?php echo pcp_apontamento_h($processo['descricao']); ?></option><?php endforeach; ?></select></label>
                <?php if ($exibirRetrabalho): ?><label class="check"><input type="checkbox" name="retrabalho" value="S" onchange="this.form.motivo_retrabalho.required=this.checked"> Retrabalho</label><label>Motivo de retrabalho<select name="motivo_retrabalho"><option value="">Selecione quando aplicável</option><?php foreach ($opcoes['retrabalho'] as $motivo): ?><option value="<?php echo (int) $motivo['id']; ?>"><?php echo pcp_apontamento_h($motivo['descricao']); ?></option><?php endforeach; ?></select></label><?php endif; ?>
                <button name="acao" value="start"<?php echo (!$opInformada || !$opcoes['processos']) ? ' disabled' : ''; ?>>Iniciar apontamento</button>
            </form>
        <?php endif; ?>
    <?php endif; ?>
