<?php if ($colaborador && !$aberto): ?><dialog class="op-dialog" data-pcp-op-dialog><div class="op-dialog__head"><p class="eyebrow">Localizar OP</p><h3>Informe o número da OP</h3><p>A OP será validada para a empresa ativa antes de liberar os processos.</p></div><form method="post" class="op-dialog__form"><input type="hidden" name="csrf" value="<?php echo pcp_apontamento_h(pcp_apontamento_csrf_token()); ?>"><input type="hidden" name="matricula" value="<?php echo pcp_apontamento_h($matricula); ?>"><label>Número da OP<input name="op_id" inputmode="numeric" pattern="[0-9]+" value="<?php echo $opInformada ?: ''; ?>" required autofocus></label><div data-pcp-op-dialog-feedback></div><div class="op-dialog__actions"><button type="button" class="secondary" data-pcp-close-op-dialog>Cancelar</button><button name="acao" value="lookup_op">Localizar OP</button></div></form></dialog><?php endif; ?>
<?php pcp_apontamento_footer();
